// Determine which trigger fired and extract optional params.
// Webhook payloads carry a .body object; schedule items do not.
const item = $input.first();
const isWebhook = !!(item.json.body !== undefined);
const triggerSource = isWebhook ? 'n8n-webhook' : 'n8n-cron';

const dryRun   = isWebhook && item.json.body?.dryRun   === true;
const docsOnly = isWebhook && item.json.body?.docsOnly === true;

const args = ['--json'];
if (dryRun)   args.push('--dry-run');
if (docsOnly) args.push('--docs-only');

const projectRoot = $env.AGENTX_PROJECT_ROOT || '/home/yb/codes/AgentX';

return [{
  json: {
    triggerSource,
    dryRun,
    docsOnly,
    projectRoot,
    command: `cd ${projectRoot} && RAG_CODEBASE_SYNC_TRIGGER=${triggerSource} ./scripts/archive-and-ingest-all.sh ${args.join(' ')}`
  }
}];

// Parse JSON output from archive-and-ingest-all.sh --json.
// On success the script writes one JSON line to stdout.
// On script error, stderr may have context; stdout may still be partial JSON.
const item = $input.first();
const raw  = (item.json.stdout || '').trim();

let parsed;
try {
  // Grab the last non-empty line in case the script emitted extra output.
  const lines = raw.split('\n').filter(l => l.trim().startsWith('{'));
  parsed = JSON.parse(lines[lines.length - 1]);
} catch (e) {
  parsed = {
    status: 'error',
    message: 'Failed to parse script stdout as JSON',
    parseError: e.message,
    stdout: raw.substring(0, 1000),
    stderr: (item.json.stderr || '').substring(0, 500)
  };
}

// Attach execution context from previous node.
parsed._trigger  = $('Prepare Args').first().json.triggerSource;
parsed._dryRun   = $('Prepare Args').first().json.dryRun;
parsed._docsOnly = $('Prepare Args').first().json.docsOnly;

return [{ json: parsed }];

// Build DataAPI server-log payload summarising the completed sync run.
const r = $input.first().json;

const archived  = r.archive?.files  ?? r.archive?.count ?? 0;
const ingested  = r.ingest?.ingested ?? 0;
const failed    = r.ingest?.failed   ?? 0;
const skipped   = r.ingest?.skipped  ?? 0;
const durationMs = r.ingest?.durationMs ?? null;

return [{
  json: {
    source: 'n8n-N2.4',
    level: 'info',
    event: 'rag-codebase-sync-complete',
    trigger: r._trigger,
    dryRun: r._dryRun,
    docsOnly: r._docsOnly,
    startedAt: r.startedAt,
    finishedAt: r.finishedAt,
    archived,
    ingested,
    failed,
    skipped,
    durationMs,
    summary: `N2.4 sync complete: archived=${archived}, ingested=${ingested}, failed=${failed}, skipped=${skipped}`
  }
}];

