// Build DataAPI server-log payload for a failed sync run.
const r = $input.first().json;

return [{
  json: {
    source: 'n8n-N2.4',
    level: 'error',
    event: 'rag-codebase-sync-error',
    trigger: r._trigger,
    dryRun: r._dryRun,
    docsOnly: r._docsOnly,
    startedAt: r.startedAt,
    finishedAt: r.finishedAt,
    message: r.message || 'Archive or ingest step failed',
    exitCode: r.exitCode,
    parseError: r.parseError,
    stdout: r.stdout,
    stderr: r.stderr,
    summary: `N2.4 sync FAILED: ${r.message || r.parseError || 'unknown error'}`
  }
}];

